+const GIT_VALUE_OPTIONS = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace']);
+
+// A short flag group such as -f or -fu (not a long --flag), containing any of `letters`.
+const shortGroupHas = (word: string, letters: string) =>
+  word.length > 1 && word[0] === '-' && word[1] !== '-' && [...word.slice(1)].some((c) => letters.includes(c));
+
+// `--name` alone or as `--name=value`.
+const longIs = (word: string, name: string) => word === name || word.startsWith(name + '=');
+
+function gitHit(args: string[]): Hit | undefined {
+  let i = 0;
+  while (i < args.length && args[i].startsWith('-')) i += GIT_VALUE_OPTIONS.has(args[i]) ? 2 : 1;
+  const sub = args[i];
+  const rest = args.slice(i + 1);
+
+  if (sub === 'push') {
+    let positional = false;
+    for (const word of rest) {
+      if (!positional && word === '--') positional = true;
+      else if (!positional && word.startsWith('-')) {
+        if (['--force', '--force-with-lease', '--mirror', '--delete', '--prune'].some((f) => longIs(word, f)) || shortGroupHas(word, 'fd'))
+          return { name: 'force-push', reason: `git push ${word} can overwrite or delete remote history` };
+      } else if (word.startsWith('+') || word.startsWith(':'))
+        return { name: 'force-push', reason: `git push refspec ${word} force-updates or deletes a remote ref` };
+    }
+  }
+
+  if (sub === 'reset' && rest.includes('--hard'))
+    return { name: 'reset-hard', reason: 'git reset --hard discards uncommitted changes' };
+
+  if (sub === 'clean') {
+    const force = rest.some((w) => w === '--force' || shortGroupHas(w, 'f'));
+    const dryRun = rest.some((w) => w === '-n' || w === '--dry-run');
+    if (force && !dryRun) return { name: 'clean-force', reason: 'git clean --force deletes untracked files' };
+  }
+
+  return undefined;
+}
+
+// A path whose value is only known at run time: variables or another user's home.
+const unresolvable = (path: string) => path.includes('$') || (path.startsWith('~') && path !== '~' && !path.startsWith('~/'));
+
+function rmHit(args: string[], cwd: string): Hit | undefined {
+  const sep = args.indexOf('--');
+  const before = sep === -1 ? args : args.slice(0, sep);
+  const after = sep === -1 ? [] : args.slice(sep + 1);
+  const flags = before.filter((w) => w.startsWith('-'));
+  const targets = [...before.filter((w) => !w.startsWith('-')), ...after];
+
+  if (!flags.some((w) => w === '--recursive' || shortGroupHas(w, 'rR'))) return undefined;
+  if (targets.length === 0) return { name: 'rm-outside', reason: 'recursive rm with no visible targets (e.g. fed by xargs)' };
+  for (const target of targets) {
+    if (unresolvable(target)) return { name: 'rm-outside', reason: `recursive rm target ${target} cannot be resolved before it runs` };
+    if (!insideWorkspace(target, cwd) || sameDir(target, cwd))
+      return { name: 'rm-outside', reason: `recursive rm target ${target} is outside the workspace or the workspace itself` };
+  }
+  return undefined;
+}
+
+function findHit(args: string[], cwd: string): Hit | undefined {
+  if (!args.some((w) => w === '-delete' || w === '-exec' || w === '-execdir')) return undefined;
+  const firstExpr = args.findIndex((w) => w.startsWith('-'));
+  const starts = firstExpr === -1 ? args : args.slice(0, firstExpr);
+  for (const start of starts.length === 0 ? ['.'] : starts) {
+    if (unresolvable(start)) return { name: 'rm-outside', reason: `find start path ${start} cannot be resolved before it runs` };
+    if (!insideWorkspace(start, cwd)) return { name: 'rm-outside', reason: `find start path ${start} is outside the workspace` };
+  }
+  return undefined;
 }

diff -ruN '--exclude=node_modules' '--exclude=.git' a/edit.ts b/edit.ts
--- a/edit.ts	2026-10-29 08:58:00.714794745 +0000
+++ b/edit.ts	2026-10-29 08:58:38.411741616 +0000
@@ -23,5 +23,96 @@
 // - nothing matched: message contains "not found", and when the first non-blank line of old_text (trimmed) occurs
 //   in some lines of content, "first line appears at line L1, L2" (at most 5 lines).
 export function applyEdit(content: string, edit: TextEdit): { content: string; applied: Applied } | { error: string } {
-  throw new Error('not implemented');
+  const { old_text, new_text } = edit;
+  if (old_text === '') return { error: 'old_text is empty; to create or overwrite a file, use write' };
+  if (old_text === new_text) return { error: 'old_text and new_text are the same; nothing to change' };
+
+  // Tier 1: exact.
+  const starts: number[] = [];
+  for (let i = content.indexOf(old_text); i !== -1; i = content.indexOf(old_text, i + old_text.length)) starts.push(i);
+  if (starts.length > 1 && !edit.replace_all) {
+    return {
+      error: `old_text matches ${starts.length} places (first at line ${lineAt(content, starts[0])}); add surrounding context to make it unique, or set replace_all`,
+    };
+  }
+  if (starts.length > 0) {
+    const last = starts[starts.length - 1];
+    return {
+      content: content.split(old_text).join(new_text),
+      applied: {
+        from: lineAt(content, starts[0]),
+        to: lineAt(content, last + old_text.length - 1),
+        tier: 'exact',
+        count: starts.length,
+      },
+    };
+  }
+
+  // Tiers 2 and 3 work on whole lines.
+  const trailingNewline = content.endsWith('\n');
+  const lines = content.split('\n');
+  if (trailingNewline) lines.pop();
+  const oldLines = toLines(old_text);
+  const newLines = toLines(new_text);
+
+  const tiers: [Tier, (s: string) => string][] = [
+    ['trailing-space', (s) => s.trimEnd()],
+    ['indentation', (s) => s.trim()],
+  ];
+  for (const [tier, norm] of tiers) {
+    const want = oldLines.map(norm);
+    const found: number[] = [];
+    for (let i = 0; i + want.length <= lines.length; i++) {
+      if (want.every((w, j) => norm(lines[i + j]) === w)) found.push(i);
+    }
+    if (found.length > 1) {
+      return {
+        error: `old_text matches ${found.length} places (${tier}) at lines ${found.map((i) => i + 1).join(', ')}; add surrounding context to make it unique`,
+      };
+    }
+    if (found.length === 0) continue;
+
+    const at = found[0];
+    const replacement = tier === 'indentation' ? reindent(newLines, oldLines, lines.slice(at, at + oldLines.length)) : newLines;
+    lines.splice(at, oldLines.length, ...replacement);
+    const out = lines.join('\n') + (trailingNewline && lines.length > 0 ? '\n' : '');
+    return { content: out, applied: { from: at + 1, to: at + oldLines.length, tier, count: 1 } };
+  }
+
+  // Nothing matched: point at where old_text's first line shows up, if anywhere.
+  let error = 'old_text not found';
+  const first = oldLines.find((l) => l.trim() !== '')?.trim();
+  if (first) {
+    const hits: number[] = [];
+    lines.forEach((l, i) => {
+      if (l.includes(first)) hits.push(i + 1);
+    });
