+import { expect, test } from 'bun:test';
+import { type EvictReason, LRU } from '../src/lru.ts';
+
+function setup(capacity = 2, ttl = 1000) {
+  const clock = { t: 0 };
+  const cache = new LRU<string, number>(capacity, ttl, () => clock.t);
+  const evicted: [string, number, EvictReason][] = [];
+  cache.onEvict = (k, v, r) => evicted.push([k, v, r]);
+  return { clock, cache, evicted };
+}
+
+test('get hit makes the entry most recently used', () => {
+  const { cache, evicted } = setup();
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  expect(cache.keys()).toEqual(['a', 'b']);
+  cache.set('c', 3);
+  expect(evicted).toEqual([['b', 2, 'capacity']]);
+  expect(cache.keys()).toEqual(['c', 'a']);
+});
+
+test('get of a missing key is undefined', () => {
+  const { cache, evicted } = setup();
+  expect(cache.get('x')).toBeUndefined();
+  expect(evicted).toEqual([]);
+});
+
+test('get does not refresh the ttl', () => {
+  const { clock, cache, evicted } = setup();
+  cache.set('a', 1);
+  clock.t = 999;
+  expect(cache.get('a')).toBe(1);
+  clock.t = 1000;
+  expect(cache.get('a')).toBeUndefined();
+  expect(evicted).toEqual([['a', 1, 'expired']]);
+});
+
+test('live while now < t + ttl; expired entry found by get is removed once', () => {
+  const { clock, cache, evicted } = setup();
+  cache.set('a', 1);
+  clock.t = 999;
+  expect(cache.get('a')).toBe(1);
+  clock.t = 1000;
+  expect(cache.get('a')).toBeUndefined();
+  expect(evicted).toEqual([['a', 1, 'expired']]);
+  expect(cache.get('a')).toBeUndefined();
+  expect(evicted.length).toBe(1);
+});
+
+test('set gives a fresh ttl and makes the entry most recent', () => {
+  const { clock, cache } = setup();
+  cache.set('a', 1);
+  cache.set('b', 2);
+  clock.t = 500;
+  cache.set('a', 10);
+  expect(cache.keys()).toEqual(['a', 'b']);
+  clock.t = 1200;
+  expect(cache.get('b')).toBeUndefined();
+  expect(cache.get('a')).toBe(10);
+});
+
+test('overwriting a key does not count against capacity', () => {
+  const { cache, evicted } = setup();
+  cache.set('a', 1);
+  cache.set('b', 2);
+  cache.set('b', 3);
+  expect(evicted).toEqual([]);
+  expect(cache.keys()).toEqual(['b', 'a']);
+});
+
+test('over capacity: expired entries go first, then a live one only if still needed', () => {
+  const { clock, cache, evicted } = setup(3);
+  cache.set('a', 1);
+  clock.t = 500;
+  cache.set('b', 2);
+  cache.set('c', 3);
+  expect(cache.get('a')).toBe(1); // a is most recently used but older
+  clock.t = 1000; // a expired, b and c live
+  cache.set('d', 4);
+  expect(evicted).toEqual([['a', 1, 'expired']]);
+  expect(cache.keys()).toEqual(['d', 'c', 'b']);
+  cache.set('e', 5);
+  expect(evicted).toEqual([['a', 1, 'expired'], ['b', 2, 'capacity']]);
+});
+
+test('capacity counts expired entries; no eviction while within capacity', () => {
+  const { clock, cache, evicted } = setup(2);
+  cache.set('a', 1);
+  clock.t = 1000;
+  cache.set('b', 2);
+  expect(evicted).toEqual([]);
+  expect(cache.size).toBe(1);
+  cache.set('c', 3);
+  expect(evicted).toEqual([['a', 1, 'expired']]);
+  expect(cache.keys()).toEqual(['c', 'b']);
+});
+
+test('delete', () => {
+  const { clock, cache, evicted } = setup();
+  cache.set('a', 1);
+  expect(cache.delete('a')).toBe(true);
+  expect(evicted).toEqual([['a', 1, 'delete']]);
+  expect(cache.delete('a')).toBe(false);
+  expect(cache.delete('missing')).toBe(false);
+  cache.set('b', 2);
+  clock.t = 2000;
+  expect(cache.delete('b')).toBe(false);
+  expect(evicted).toEqual([['a', 1, 'delete'], ['b', 2, 'expired']]);
+  expect(cache.delete('b')).toBe(false);
+  expect(evicted.length).toBe(2);
+});
+
+test('size and keys count only live entries', () => {
+  const { clock, cache } = setup(3);
+  cache.set('a', 1);
+  clock.t = 500;
+  cache.set('b', 2);
+  expect(cache.size).toBe(2);
+  clock.t = 1000;
+  expect(cache.size).toBe(1);
+  expect(cache.keys()).toEqual(['b']);
+  clock.t = 1500;
+  expect(cache.size).toBe(0);
+  expect(cache.keys()).toEqual([]);
